"""Random search over full-bound requests to find the worst-case state count."""
import json, sys, time, random
sys.path.insert(0,'/app')
from main import compile_threads, STORE, LOAD, FENCE, XCHG

def explore_count(mem0, progs):
    n = len(progs); lens=[len(p) for p in progs]; nrange=range(n)
    start=(mem0,(0,)*n,((),)*n,((),)*n)
    visited={start}; stack=[start]; outcomes=set(); gen=0
    while stack:
        state=stack.pop(); mem,pcs,bufs,obs=state; moved=False
        for t in nrange:
            pc=pcs[t]
            if pc==lens[t]: continue
            kind,a,w,nb=progs[t][pc]; buf=bufs[t]
            gen+=1
            if kind==STORE:
                st=(mem,pcs[:t]+(pc+1,)+pcs[t+1:],bufs[:t]+(buf+((a,nb),),)+bufs[t+1:],obs)
            elif kind==LOAD:
                val=0;shift=0
                for i in range(w):
                    addr=a+i;b=None
                    for ent in reversed(buf):
                        sa,snb=ent
                        if sa<=addr<sa+len(snb): b=snb[addr-sa]; break
                    if b is None: b=mem[addr]
                    val|=b<<shift; shift+=8
                st=(mem,pcs[:t]+(pc+1,)+pcs[t+1:],bufs,obs[:t]+(obs[t]+(val,),)+obs[t+1:])
            elif kind==FENCE:
                if buf: continue
                st=(mem,pcs[:t]+(pc+1,)+pcs[t+1:],bufs,obs)
            else:
                if buf: continue
                val=int.from_bytes(mem[a:a+w],'little'); nmem=mem[:a]+nb+mem[a+w:]
                st=(nmem,pcs[:t]+(pc+1,)+pcs[t+1:],bufs,obs[:t]+(obs[t]+(val,),)+obs[t+1:])
            moved=True
            if st not in visited: visited.add(st); stack.append(st)
        for t in nrange:
            buf=bufs[t]
            if buf:
                a,nb=buf[0]; gen+=1
                nmem=mem[:a]+nb+mem[a+len(nb):]
                st=(nmem,pcs,bufs[:t]+(buf[1:],)+bufs[t+1:],obs)
                moved=True
                if st not in visited: visited.add(st); stack.append(st)
        if not moved: outcomes.add((obs,mem))
    return len(visited), len(outcomes), gen

def rand_case(rng, nmem=8, nthreads=3, total=10, kinds=None):
    counts=[0]*nthreads
    for _ in range(total):
        t=rng.randrange(nthreads)
        if counts[t]<4: counts[t]+=1
    kinds=kinds or ['store','load','load','store','xchg','fence']
    threads=[]
    for c in counts:
        prog=[]
        for _ in range(c):
            k=rng.choice(kinds)
            w=rng.choice([x for x in (1,1,1,2,2,4) if x<=nmem])
            a=rng.randint(0,nmem-w)
            if k=='store': prog.append(['store',a,w,rng.randint(0,(1<<(8*w))-1)])
            elif k=='load': prog.append(['load',a,w])
            elif k=='fence': prog.append(['fence'])
            else: prog.append(['xchg',a,w,rng.randint(0,(1<<(8*w))-1)])
        threads.append(prog)
    return {'memory':[rng.randint(0,255) for _ in range(nmem)],'threads':threads}

def main():
    seed=int(sys.argv[1]); iters=int(sys.argv[2])
    rng=random.Random(seed)
    worst=(0,None,None)
    for i in range(iters):
        req=rand_case(rng)
        t=time.time(); nv,no,gen=explore_count(bytes(req['memory']), compile_threads(req['threads'])); dt=time.time()-t
        if nv>worst[0]: worst=(nv,dt,json.dumps(req))
        if dt>2.0: print('SLOW',dt,nv,no,json.dumps(req))
    print('max states',worst[0],'time %.3f'%worst[1])
    print('worst case:',worst[2])
main()
