import json,sys,time,random
sys.path.insert(0,'/app')
from perfsearch import explore_count
from main import compile_threads

NMEM=8; NT=3; TOTAL=10
KINDS=['store','load','load','store','xchg','fence']

def rand_prog(rng):
    counts=[0]*NT
    for _ in range(TOTAL):
        t=rng.randrange(NT)
        if counts[t]<4: counts[t]+=1
    th=[]
    for c in counts:
        p=[]
        for _ in range(c):
            k=rng.choice(KINDS)
            if k=='fence': p.append(['fence']); continue
            w=rng.choice([1,2,4]); a=rng.randint(0,NMEM-w)
            if k=='load': p.append(['load',a,w])
            else: p.append([k,a,w,rng.randint(0,(1<<(8*w))-1)])
        th.append(p)
    return {'memory':[rng.randint(0,255) for _ in range(NMEM)],'threads':th}

def mutate(rng,req):
    r=json.loads(json.dumps(req))
    th=r['threads']
    t=rng.randrange(len(th))
    if not th[t]: return r
    i=rng.randrange(len(th[t])); ins=th[t][i]
    op=rng.choice(['kind','addr','width','value','mem'])
    if op=='mem':
        r['memory'][rng.randrange(NMEM)]=rng.randint(0,255)
    elif ins[0]=='fence':
        w=rng.choice([1,2,4]); a=rng.randint(0,NMEM-w)
        th[t][i]=['load',a,w] if rng.random()<.5 else ['store',a,w,rng.randint(0,(1<<(8*w))-1)]
    elif op=='kind':
        k=rng.choice(KINDS)
        if k=='fence': th[t][i]=['fence']
        else:
            w=ins[2] if len(ins)>2 else rng.choice([1,2,4]); w=min(w,4); a=rng.randint(0,NMEM-w)
            if k=='load': th[t][i]=['load',a,w]
            else: th[t][i]=[k,a,w,rng.randint(0,(1<<(8*w))-1)]
    elif op=='width':
        if len(ins)>2:
            w=rng.choice([1,2,4]); a=rng.randint(0,NMEM-w); ins[1]=a; ins[2]=w
            if len(ins)>3: ins[3]=rng.randint(0,(1<<(8*w))-1)
    elif op=='addr' and len(ins)>2:
        ins[1]=rng.randint(0,NMEM-ins[2])
    else:
        if len(ins)>3: ins[3]=rng.randint(0,(1<<(8*ins[2]))-1)
    return r

def score(req):
    nv,no,g=explore_count(bytes(req['memory']),compile_threads(req['threads']))
    return nv,no

def main():
    rng=random.Random(int(sys.argv[1])); rounds=int(sys.argv[2])
    best=None; bestsc=(0,0); t0=time.time()
    for it in range(rounds):
        cur=rand_prog(rng); sc=score(cur)
        for _ in range(60):
            cand=mutate(rng,cur)
            try: cs=score(cand)
            except Exception: continue
            if cs>sc: cur,sc=cand,cs
        if sc>bestsc:
            bestsc=sc; best=cur
            print('iter',it,'states',sc[0],'outcomes',sc[1],'%.1fs'%(time.time()-t0)); sys.stdout.flush()
        if time.time()-t0>240: break
    print('BEST states',bestsc[0],'outcomes',bestsc[1])
    print(json.dumps(best))
main()
